#!/usr/bin/env node
/**
 * npm run explainer:stats: copies the engine's own per-relationship-type edge counts for the /explainer
 * "sparse matrices" scene into public/explainer/graph-stats.json.
 *
 * Source: ../docs/GRAPH_SCHEMA.md, which is GENERATED by scripts/gen_graph_schema.py from the live graphs
 * (db.meta.stats, template Q-SCHEMA-1); never hand-edited. Only the `golden_acme` column is copied, verbatim:
 * the graph's node and edge totals, and the edge count of every relationship type that has edges. Nothing is
 * derived here (densities are computed in the UI from these counts). Also copies the algo.* procedure names the
 * smoke run resolved on the pinned engine (backend/faultline/graph/algo/resolved.json), for the end card.
 * Re-run after regenerating GRAPH_SCHEMA.md or re-running smoke.
 * Fails loudly (exit 1) when the file is missing or its tables cannot be read.
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const frontend = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const src = path.resolve(frontend, "..", "docs", "GRAPH_SCHEMA.md");
const resolvedSrc = path.resolve(frontend, "..", "backend", "faultline", "graph", "algo", "resolved.json");
const out = path.join(frontend, "public", "explainer", "graph-stats.json");
const GRAPH = "golden_acme";

const fail = (msg) => {
  console.error(`explainer:stats FAILED: ${msg}`);
  process.exit(1);
};

let md;
try {
  md = await readFile(src, "utf8");
} catch (e) {
  fail(`cannot read ${path.relative(frontend, src)}: ${e.message} (run scripts/gen_graph_schema.py)`);
}
if (!md.includes("GENERATED by `scripts/gen_graph_schema.py`")) fail("GRAPH_SCHEMA.md is not the generated file");

const cells = (line) => line.split("|").slice(1, -1).map((c) => c.trim());
const lines = md.split("\n");
const engine = /^Engine: (FalkorDB [0-9.]*[0-9])/m.exec(md)?.[1] ?? null;

// Summary table: | graph | nodes | edges | labels with nodes | relationship types with edges | ...
const summary = lines.find((l) => l.startsWith(`| \`${GRAPH}\` |`));
if (!summary) fail(`no summary row for ${GRAPH}`);
const [, nodes, edges, , relTypesWithEdges] = cells(summary).map((c) => c.replace(/`/g, ""));
const num = (s, what) => {
  const n = Number(s);
  if (!Number.isInteger(n) || n < 0) fail(`${what} is not a count: ${JSON.stringify(s)}`);
  return n;
};

// Relationship table: | type | lifecycle | acme | globex | endpoint pairs | read by templates |
const header = lines.findIndex((l) => /^\| type \| lifecycle \| acme \| globex \|/.test(l));
if (header < 0) fail("relationship-type table not found");
const types = [];
for (let i = header + 2; i < lines.length && lines[i].startsWith("|"); i++) {
  const [type, lifecycle, acme] = cells(lines[i]);
  const n = num(acme, `edge count of ${type}`);
  if (n > 0) types.push({ type: type.replace(/`/g, ""), lifecycle, edges: n });
}
types.sort((a, b) => b.edges - a.edges || a.type.localeCompare(b.type));
let resolved;
try {
  resolved = JSON.parse(await readFile(resolvedSrc, "utf8"));
} catch (e) {
  fail(`cannot read ${path.relative(frontend, resolvedSrc)}: ${e.message} (run make smoke)`);
}
const algorithms = Object.values(resolved.procedures ?? {}).map((p) => p?.name).filter((n) => typeof n === "string" && n.startsWith("algo."));
if (!algorithms.length) fail("resolved.json lists no algo.* procedures");
const doc = {
  source: "docs/GRAPH_SCHEMA.md (scripts/gen_graph_schema.py, db.meta.stats)",
  graph: GRAPH,
  engine,
  nodes: num(nodes, "node total"),
  edges: num(edges, "edge total"),
  rel_types_with_edges: num(relTypesWithEdges, "relationship types with edges"),
  rel_types: types,
  algorithms,
  algorithms_engine: typeof resolved.engine === "string" ? resolved.engine : null,
};
if (doc.rel_types.length !== doc.rel_types_with_edges) {
  fail(`table lists ${doc.rel_types.length} types with edges, summary says ${doc.rel_types_with_edges}`);
}
if (doc.rel_types.reduce((a, t) => a + t.edges, 0) !== doc.edges) fail("per-type counts do not sum to the edge total");
await mkdir(path.dirname(out), { recursive: true });
await writeFile(out, JSON.stringify(doc, null, 2) + "\n");
console.log(`explainer:stats: ${doc.rel_types.length} relationship types, ${doc.nodes} nodes / ${doc.edges} edges of ${GRAPH} → public/explainer/graph-stats.json`);
